// Boundary arrangement union for small, convex paving pieces. The output has no coincident faces.
const cross=(a,b)=>a[0]*b[1]-a[1]*b[0],sub=(a,b)=>[a[0]-b[0],a[1]-b[1]],dot=(a,b)=>a[0]*b[0]+a[1]*b[1],eps=1e-7,key=p=>p.map(n=>Math.round(n*1e6)).join(',');
export const signedArea=poly=>poly.reduce((s,p,i)=>{const q=poly[(i+1)%poly.length];return s+cross(p,q);},0)/2;
function boundaryAt(poly,p){for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],u=sub(b,a),v=sub(p,a);if(Math.abs(cross(u,v))<eps&&dot(v,u)>=-eps&&dot(v,u)<=dot(u,u)+eps)return u;}return null;}
export function pointInPolygon(poly,p){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
export function unionPolygons(input){const polygons=input.map(p=>signedArea(p)<0?[...p].reverse():p),edges=polygons.flatMap((p,id)=>p.map((a,i)=>({a,b:p[(i+1)%p.length],id}))),kept=[];
 for(const edge of edges){const {a,b,id}=edge,u=sub(b,a),cuts=[0,1];for(const other of edges){if(other.id===id)continue;const v=sub(other.b,other.a),w=sub(other.a,a),den=cross(u,v);if(Math.abs(den)>eps){const t=cross(w,v)/den,q=cross(w,u)/den;if(t>eps&&t<1-eps&&q>=-eps&&q<=1+eps)cuts.push(t);}else if(Math.abs(cross(u,w))<eps){for(const p of [other.a,other.b]){const t=dot(sub(p,a),u)/dot(u,u);if(t>eps&&t<1-eps)cuts.push(t);}}}cuts.sort((a,b)=>a-b);for(let i=1;i<cuts.length;i++){if(cuts[i]-cuts[i-1]<eps)continue;const t=(cuts[i]+cuts[i-1])/2,mid=[a[0]+u[0]*t,a[1]+u[1]*t];let covered=false;for(let j=0;j<polygons.length;j++){if(j===id)continue;const boundary=boundaryAt(polygons[j],mid);if(boundary){if(dot(u,boundary)<0||id>j){covered=true;break;}}else if(pointInPolygon(polygons[j],mid)){covered=true;break;}}if(!covered)kept.push({a:[a[0]+u[0]*cuts[i-1],a[1]+u[1]*cuts[i-1]],b:[a[0]+u[0]*cuts[i],a[1]+u[1]*cuts[i]]});}}
 const byStart=new Map();kept.forEach((e,i)=>{const k=key(e.a);if(!byStart.has(k))byStart.set(k,[]);byStart.get(k).push(i);});const visited=new Set(),rings=[];for(let i=0;i<kept.length;i++){if(visited.has(i))continue;const ring=[],first=key(kept[i].a);let index=i,closed=false;for(let steps=0;steps<=kept.length;steps++){if(visited.has(index))break;const e=kept[index];visited.add(index);ring.push(e.a);if(key(e.b)===first){closed=true;break;}const next=(byStart.get(key(e.b))??[]).find(j=>!visited.has(j));if(next===undefined)break;index=next;}if(!closed)throw Error('Open paving union boundary');if(ring.length>2&&Math.abs(signedArea(ring))>eps)rings.push(ring);}return rings;
}
export function pavingPolygons(paths,{plaza}={}){const parts=[],circle=(p,r)=>Array.from({length:20},(_,i)=>[p[0]+Math.cos(i*Math.PI/10)*r,p[1]+Math.sin(i*Math.PI/10)*r]);for(const path of paths){for(const p of path.points)parts.push(circle(p,path.width/2));for(let i=1;i<path.points.length;i++){const a=path.points[i-1],b=path.points[i],d=sub(b,a),length=Math.hypot(...d);if(length<eps)continue;const n=[-d[1]/length*path.width/2,d[0]/length*path.width/2];parts.push([[a[0]-n[0],a[1]-n[1]],[b[0]-n[0],b[1]-n[1]],[b[0]+n[0],b[1]+n[1]],[a[0]+n[0],a[1]+n[1]]]);}}if(plaza)parts.push(circle(plaza.center,plaza.radius));return unionPolygons(parts);}
